package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class Phase5ePermissionGuardTest{@Test void selectionActionsAreExactIndependentAndAgencyWide(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);RspSelectionDecisionPermissionGuard guard=new RspSelectionDecisionPermissionGuard(client);EffectiveFeaturePermission denied=new EffectiveFeaturePermission(RspSelectionDecisionPermissionGuard.FEATURE,false,true,true,true,false,false,true,false,false,false,true,PermissionDataScope.AGENCY_WIDE);when(client.resolve(eq(RspSelectionDecisionPermissionGuard.FEATURE),anyString())).thenReturn(denied);assertThatCode(()->guard.require(PrimeHrAction.SUBMIT,"Bearer token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.APPROVE,"Bearer token")).isInstanceOf(AccessDeniedException.class);assertThatCode(()->guard.require(PrimeHrAction.FINALIZE,"Bearer token")).doesNotThrowAnyException();EffectiveFeaturePermission wrongScope=new EffectiveFeaturePermission(RspSelectionDecisionPermissionGuard.FEATURE,false,true,true,true,false,false,true,true,false,false,true,PermissionDataScope.OWN_RECORDS);when(client.resolve(eq(RspSelectionDecisionPermissionGuard.FEATURE),anyString())).thenReturn(wrongScope);assertThatThrownBy(()->guard.require(PrimeHrAction.APPROVE,"Bearer token")).isInstanceOf(AccessDeniedException.class);}@Test void handoffUsesItsOwnAgencyWideFeature(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);RspAppointmentHandoffPermissionGuard guard=new RspAppointmentHandoffPermissionGuard(client);EffectiveFeaturePermission allowed=new EffectiveFeaturePermission(RspAppointmentHandoffPermissionGuard.FEATURE,false,true,true,false,false,false,true,false,false,false,true,PermissionDataScope.AGENCY_WIDE);when(client.resolve(eq(RspAppointmentHandoffPermissionGuard.FEATURE),anyString())).thenReturn(allowed);assertThatCode(()->guard.require(PrimeHrAction.ADD,"Bearer token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.EDIT,"Bearer token")).isInstanceOf(AccessDeniedException.class);}}
